  "inlineSchema": "// Schema do painel de follow-up para WhatsApp.\n// Após alterar este arquivo rode: pnpm prisma:generate && pnpm prisma:migrate\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../lib/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum LeadStatus {\n  novo\n  em_campanha\n  respondeu\n  qualificado\n  encerrado\n}\n\nenum CampaignStatus {\n  ativa\n  pausada\n  encerrada\n  rascunho\n}\n\nenum EventType {\n  mensagem_enviada\n  falha\n  resposta\n  qualificado\n  campanha_iniciada\n  campanha_encerrada\n}\n\n/// Nível de severidade dos logs de sistema (não confundir com eventos de lead).\nenum AppLogNivel {\n  info\n  aviso\n  erro\n  critico\n}\n\nmodel Lead {\n  id       String @id @default(cuid())\n  nome     String\n  telefone String\n\n  // Dimensões de segmentação. Ficam como texto para que novos produtos ou\n  // marcas não exijam uma migration de enum.\n  produto String\n  marca   String\n  persona String\n  regiao  String\n\n  status LeadStatus @default(novo)\n\n  // Anotações livres da equipe sobre o lead. Opcionais e editáveis a qualquer\n  // momento pela página de detalhe do lead.\n  notas String?\n\n  campanhaId String?\n  campanha   Campaign? @relation(fields: [campanhaId], references: [id], onDelete: SetNull)\n\n  campanhas LeadCampaign[]\n\n  entradaCampanhaEm DateTime?\n  criadoEm          DateTime  @default(now())\n  atualizadoEm      DateTime  @updatedAt\n\n  eventos TimelineEvent[]\n\n  // A listagem ordena por data de criação e filtra por campanha e status.\n  @@index([campanhaId])\n  @@index([status])\n  @@index([criadoEm])\n}\n\nmodel Campaign {\n  id        String         @id @default(cuid())\n  nome      String\n  descricao String?\n  status    CampaignStatus @default(rascunho)\n\n  recorrenciaDias Int       @default(7)\n  dataFinal       DateTime?\n\n  // Marca o momento do último (re)início da campanha. A dedupe de envio só\n  // considera mensagens disparadas a partir daqui, então reiniciar a campanha\n  // permite reenviar a mensagem inicial aos leads.\n  reiniciadaEm DateTime?\n\n  // Filtros de público da campanha (nulo = sem restrição na dimensão).\n  filtroProduto String?\n  filtroMarca   String?\n  filtroPersona String?\n  filtroRegiao  String?\n\n  criadoEm     DateTime @default(now())\n  atualizadoEm DateTime @updatedAt\n\n  mensagens     CampaignMessage[]\n  leads         Lead[]\n  leadCampaigns LeadCampaign[]\n  eventos       TimelineEvent[]\n\n  @@index([status])\n  @@index([criadoEm])\n}\n\nmodel LeadCampaign {\n  id String @id @default(cuid())\n\n  leadId String\n  lead   Lead   @relation(fields: [leadId], references: [id], onDelete: Cascade)\n\n  campanhaId String\n  campanha   Campaign @relation(fields: [campanhaId], references: [id], onDelete: Cascade)\n\n  criadoEm DateTime @default(now())\n\n  // Momento agendado para a próxima mensagem deste lead nesta campanha.\n  // Definido ao pular manualmente uma mensagem: zera o contador e passa a\n  // contar até o próximo disparo (ou até a recorrência, se não houver mais).\n  proximaMensagemEm DateTime?\n\n  // Marca um reinício de ciclo apenas para este lead (ex.: pular a partir da\n  // última mensagem). Entra no cálculo de dedupe junto de Campaign.reiniciadaEm\n  // para liberar o reenvio da sequência a este lead específico.\n  cicloReiniciadoEm DateTime?\n\n  @@unique([leadId, campanhaId])\n  @@index([campanhaId])\n  @@index([leadId])\n}\n\nmodel CampaignMessage {\n  id      String @id @default(cuid())\n  dia     Int\n  horario String\n  texto   String\n\n  campanhaId String\n  campanha   Campaign @relation(fields: [campanhaId], references: [id], onDelete: Cascade)\n\n  eventos TimelineEvent[]\n\n  // A sequência é sempre lida na ordem do dia de disparo.\n  @@index([campanhaId, dia])\n}\n\n/// Produtos cadastrados pela equipe na página de Segmentação.\n/// O nome é a chave de negócio: os leads guardam o produto como texto (o nome),\n/// então esta tabela é apenas o catálogo canônico de opções selecionáveis.\n/// Produtos inativos deixam de aparecer como opção em novos leads, mas não\n/// afetam leads que já usam aquele nome.\nmodel Produto {\n  id        String  @id @default(cuid())\n  nome      String  @unique\n  descricao String?\n  ativo     Boolean @default(true)\n\n  criadoEm     DateTime @default(now())\n  atualizadoEm DateTime @updatedAt\n\n  @@index([ativo, nome])\n}\n\n/// Preferências da engine. Tabela de linha única: `id` é fixo em \"default\"\n/// para que um upsert simples sirva tanto para criar quanto para atualizar.\nmodel Settings {\n  id String @id @default(\"default\")\n\n  remetente  String @default(\"Engine Follow-up\")\n  numero     String @default(\"\")\n  assinatura String @default(\"\")\n\n  fuso                String  @default(\"America/Sao_Paulo\")\n  janelaInicio        String  @default(\"09:00\")\n  janelaFim           String  @default(\"20:00\")\n  limiteDiario        Int     @default(300)\n  respeitarJanela     Boolean @default(true)\n  pausarNoFimDeSemana Boolean @default(true)\n  notificarFalhas     Boolean @default(true)\n\n  atualizadoEm DateTime @updatedAt\n}\n\n/// Webhooks de saída configurados na página de Integrações.\n/// O limite de 5 registros é aplicado na camada de serviço.\nmodel Webhook {\n  id     String  @id @default(cuid())\n  nome   String\n  url    String\n  secret String  @default(\"\")\n  ativo  Boolean @default(true)\n\n  /// Chaves dos eventos assinados (ver lib/webhook-events.ts).\n  /// Guardadas como lista de texto para que novos eventos não exijam migration.\n  eventos String[]\n\n  ultimoEnvioEm     DateTime?\n  ultimoEnvioStatus Int?\n\n  criadoEm     DateTime @default(now())\n  atualizadoEm DateTime @updatedAt\n\n  @@index([criadoEm])\n}\n\n/// Erros e avisos de sistema — Evolution API, banco de dados, actions etc.\n/// Separado de TimelineEvent porque não pertence ao contexto de um lead.\nmodel AppLog {\n  id       String      @id @default(cuid())\n  nivel    AppLogNivel @default(erro)\n  origem   String /// Ex: \"evolution\", \"campaigns\", \"leads\", \"webhooks\"\n  mensagem String\n  detalhes String? /// Stack trace, resposta HTTP, etc.\n  data     DateTime    @default(now())\n\n  @@index([data])\n  @@index([nivel, data])\n  @@index([origem, data])\n}\n\nmodel TimelineEvent {\n  id        String    @id @default(cuid())\n  tipo      EventType\n  descricao String\n  detalhes  String?\n  data      DateTime  @default(now())\n  sucesso   Boolean   @default(true)\n\n  leadId String\n  lead   Lead   @relation(fields: [leadId], references: [id], onDelete: Cascade)\n\n  campanhaId String?\n  campanha   Campaign? @relation(fields: [campanhaId], references: [id], onDelete: SetNull)\n\n  mensagemId String?\n  mensagem   CampaignMessage? @relation(fields: [mensagemId], references: [id], onDelete: SetNull)\n\n  // O feed e os relatórios varrem por data, tipo e agrupam por lead/campanha.\n  @@index([data])\n  @@index([tipo, data])\n  @@index([leadId, data])\n  @@index([campanhaId])\n  @@index([mensagemId])\n}\n\n/// Token de autenticação para o webhook de entrada (linha única: id=\"default\").\n/// Permite que sistemas externos enviem eventos para este painel via POST.\nmodel InboundWebhookToken {\n  id    String  @id @default(\"default\")\n  token String /// Valor gerado: whin_<64 chars hex>\n  ativo Boolean @default(true)\n\n  ultimoUsoEm  DateTime?\n  criadoEm     DateTime  @default(now())\n  atualizadoEm DateTime  @updatedAt\n}\n\n/// Eventos recebidos pelo webhook de entrada (/api/webhook/entrada).\n/// Armazenados para auditoria e visibilidade na UI.\nmodel InboundEvent {\n  id         String   @id @default(cuid())\n  evento     String /// Nome do evento enviado pelo sistema externo.\n  origem     String? /// IP/host de origem capturado do header x-forwarded-for.\n  payload    Json /// Corpo completo recebido (dados livres).\n  recebidoEm DateTime @default(now())\n\n  @@index([recebidoEm])\n  @@index([evento, recebidoEm])\n}\n",
